def variants(shape):
 ret=[]
 for k in range(4):
  arr={(r,c) for r,c in shape}
  for _ in range(k):arr={(c,-r) for r,c in arr}
  for refl in [False,True]:
   a={(r,-c if refl else c) for r,c in arr}
   mr=min(r for r,c in a);mc=min(c for r,c in a)
   z=frozenset((r-mr,c-mc) for r,c in a)
   if z not in ret:ret.append(z)
 return ret
